// Pra cada from_numero com >50 msgs, monta prompt de sumarizacao
const items_in = items.filter(i => i.json && i.json.from_numero);
if (!items_in.length) return [];

return items_in.map(it => {
  const j = it.json;
  const quemRaw = String(j.dono_nome || '').trim();
  const quem = (!quemRaw || /^\d+$/.test(quemRaw)) ? 'o usuario' : quemRaw;
  const systemPrompt = `Voce vai resumir uma conversa de WhatsApp entre ${quem} (\"user\") e a Giulia Mascarenhas (\"assistant\", a secretaria virtual). Chame o usuario de ${quem}; nao use outro nome. Retorne um resumo curto e factual em PT-BR, capturando:\n- Tipos de coisas que ele pediu (gastos, lembretes, contatos, msgs pra terceiros, etc)\n- Pessoas mencionadas (com numero se aparecer)\n- Decisoes ou agendamentos importantes\n- Preferencias ou padroes que voce notou\n\nMaximo 800 caracteres. Linguagem direta. Sem hifens em listas.`;
  return {
    json: {
      from_numero: j.from_numero,
      msg_count: j.msg_count,
      ids: j.ids,
      periodo_inicio: j.periodo_inicio,
      periodo_fim: j.periodo_fim,
      gemini_body: {
        contents: [{ parts: [{ text: 'Conversa:\n' + (j.texto_conversas || '').substring(0, 50000) }] }],
        systemInstruction: { parts: [{ text: systemPrompt }] },
        generationConfig: { temperature: 0.3, maxOutputTokens: 1200 }
      }
    }
  };
});

// Pega resumo do Gemini e monta SQL pra inserir resumo + deletar msgs antigas
const input = items[0].json;
const prep = $('Preparar Prompts').first().json;
let resumo = '';
// ignora partes de raciocinio (thought) do modelo: so o texto final conta
try {
  const partes = (input.candidates?.[0]?.content?.parts || []).filter(p => p && p.text && !p.thought);
  resumo = partes.map(p => p.text).join('').trim();
} catch(e) {}
resumo = (resumo || '').trim().substring(0, 2000);
if (!resumo) return [];
const esc = s => String(s || '').replace(/'/g, "''");

// SQL: insere resumo + deleta msgs antigas
const ids = Array.isArray(prep.ids) ? prep.ids.filter(Boolean) : [];
if (!ids.length) return [];
const idsSql = ids.join(',');
const sql = `INSERT INTO giulia_memoria_resumos (from_numero, resumo, periodo_inicio, periodo_fim, msg_count) VALUES ('${esc(prep.from_numero)}', '${esc(resumo)}', '${prep.periodo_inicio}'::TIMESTAMP, '${prep.periodo_fim}'::TIMESTAMP, ${prep.msg_count}) RETURNING id;\nDELETE FROM giulia_memoria WHERE id IN (${idsSql}) RETURNING id;`;
return [{ json: { sql, from_numero: prep.from_numero, msg_count: prep.msg_count, resumo_len: resumo.length } }];

