// 09/11: Gemini -> Claude Opus 5.5. Converte o gemini_body montado acima no corpo da API do Claude.
const j = $input.item.json;
const gb = j.gemini_body || {};
const sys = ((gb.systemInstruction || {}).parts || []).map(p => p.text || '').filter(Boolean).join('\n');
const msgs = [];
for (const c of (gb.contents || [])) {
  const role = c.role === 'model' ? 'assistant' : 'user';
  const content = [];
  for (const p of (c.parts || [])) {
    if (p.text) content.push({ type: 'text', text: p.text });
    const d = p.inline_data || p.inlineData;
    if (d && d.data) {
      const mt = String(d.mime_type || d.mimeType || '').toLowerCase().split(';')[0].trim();
      if (/^image\/(jpeg|jpg|png|gif|webp)$/.test(mt)) content.push({ type: 'image', source: { type: 'base64', media_type: mt === 'image/jpg' ? 'image/jpeg' : mt, data: d.data } });
      else if (mt === 'application/pdf') content.push({ type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: d.data } });
      else if (mt.startsWith('text/')) { let t = ''; try { t = Buffer.from(d.data, 'base64').toString('utf8'); } catch (e) {} content.push({ type: 'text', text: 'Conteudo do arquivo:\n' + t.substring(0, 100000) }); }
      else content.push({ type: 'text', text: '[anexo ' + (mt || 'desconhecido') + ' que nao consigo ler]' });
    }
  }
  if (!content.length) content.push({ type: 'text', text: '(vazio)' });
  if (msgs.length && msgs[msgs.length - 1].role === role) msgs[msgs.length - 1].content.push(...content);
  else msgs.push({ role, content });
}
if (!msgs.length || msgs[0].role !== 'user') msgs.unshift({ role: 'user', content: [{ type: 'text', text: '(inicio)' }] });
if (msgs[msgs.length - 1].role !== 'user') msgs.push({ role: 'user', content: [{ type: 'text', text: 'Continue.' }] });
const gc = gb.generationConfig || {};
const ehJson = String(gc.responseMimeType || '').includes('json');
const claude_body = {
  model: 'claude-opus-5-5',
  // o Opus 5.5 sempre pensa antes de responder e o raciocinio conta no max_tokens: folga sobre o limite antigo
  max_tokens: Math.max(4000, Math.min(16000, (parseInt(gc.maxOutputTokens, 10) || 4000) * 2)),
  system: sys + (ehJson ? '\n\nResponda SOMENTE com o objeto JSON pedido acima, sem texto antes ou depois e sem bloco de codigo.' : ''),
  messages: msgs,
  output_config: { effort: 'low' },
  fallbacks: 'default'
};
if (!claude_body.system) delete claude_body.system;  // a API recusa system vazio
return { json: { ...j, claude_body } };

// 09/11: resposta do Claude -> formato que o codigo abaixo ja le (candidates/parts/finishReason)
const r = $input.item.json || {};
if (r.error || !Array.isArray(r.content)) {
  return { json: r.error ? r : { error: { message: 'Claude sem content: ' + JSON.stringify(r).substring(0, 300) } } };
}
const text = r.content.filter(b => b && b.type === 'text').map(b => b.text || '').join('');
const fr = ({ end_turn: 'STOP', stop_sequence: 'STOP', max_tokens: 'MAX_TOKENS', refusal: 'SAFETY' })[r.stop_reason] || String(r.stop_reason || '').toUpperCase();
const u = r.usage || {};
return { json: {
  candidates: [{ content: { role: 'model', parts: [{ text }] }, finishReason: fr }],
  usageMetadata: { promptTokenCount: (u.input_tokens || 0) + (u.cache_read_input_tokens || 0) + (u.cache_creation_input_tokens || 0), candidatesTokenCount: u.output_tokens || 0 },
  modelVersion: r.model || 'claude', claude_stop_reason: r.stop_reason || null
} };
